<template>
<div class="app-container exchange-workbench">
 <div class="page-title"><div><h2>业务换货</h2><p class="muted">按待办处理换货，退回与换出分别跟踪，所有履约可追溯到原订单。</p></div><router-link to="/oms-order/syncTasks?kind=EXCHANGE"><el-button size="small">同步任务</el-button></router-link></div>
 <el-form inline size="small" class="filters" @submit.native.prevent="search"><el-form-item label="单号"><el-input v-model.trim="query.number" clearable placeholder="OMS 换货单 / 平台换货单号 / 原平台单号" style="width:290px" @keyup.enter.native="search" /></el-form-item><el-form-item label="渠道 / 店铺"><el-select v-model="query.channelId" filterable clearable><el-option v-for="c in shops" :key="c.channel_id" :label="c.channel_name" :value="c.channel_id" /></el-select></el-form-item><el-form-item label="换货阶段"><el-select v-model="query.phase" clearable><el-option label="售中换货" value="DURING_SALE" /><el-option label="售后换货" value="AFTER_SALE" /><el-option label="阶段待核对" value="UNKNOWN" /></el-select></el-form-item><el-form-item label="业务来源"><el-select v-model="query.kind" clearable><el-option label="平台换货申请" value="PLATFORM" /><el-option label="客服协商" value="INTERNAL" /></el-select></el-form-item><el-form-item><el-button type="primary" icon="el-icon-search" @click="search">查询</el-button><el-button @click="reset">重置</el-button><el-button type="text" @click="more = !more">{{ more ? '收起筛选' : '更多筛选' }}</el-button></el-form-item><template v-if="more"><el-form-item label="OMS 状态"><el-select v-model="query.state" clearable><el-option v-for="(name,key) in states" :key="key" :label="name" :value="key" /></el-select></el-form-item><el-form-item label="问题"><el-select v-model="query.problem" clearable><el-option v-for="(name,key) in problems" :key="key" :label="name" :value="key" /></el-select></el-form-item></template></el-form>
 <div class="toolbar"><div><el-button v-hasPermi="['order:exchange:create']" size="small" type="primary" @click="openCreate">创建协商换货</el-button><el-button v-hasPermi="['order:exchange:sync']" size="small" @click="openSync">同步平台申请</el-button><el-button v-hasPermi="['order:exchange:sync']" type="text" @click="showTasks">查看同步任务</el-button></div><el-button size="small" icon="el-icon-refresh" @click="load">刷新列表</el-button></div>
 <el-tabs :value="query.bucket" @tab-click="changeBucket"><el-tab-pane v-for="b in buckets" :key="b.key" :name="b.key" :label="b.label + '（' + (counts[b.key] || 0) + '）'" /></el-tabs><el-alert v-if="listError" type="error" :closable="false" title="换货列表加载失败，请刷新重试" />
 <el-table v-loading="loading" :data="rows" row-key="id" :empty-text="listError ? '列表暂未加载' : '当前分类暂无待办'">
  <el-table-column label="换货 / 原订单" min-width="330"><template slot-scope="s"><div class="exchange-number-row"><span class="number-label">OMS 换货单号</span><el-button class="number number-value" type="text" @click="open(s.row.id)">{{ s.row.exchange_sn }}</el-button><el-button v-clipboard:copy="s.row.exchange_sn" v-clipboard:success="copied" v-clipboard:error="copyFailed" type="text" icon="el-icon-document-copy" aria-label="复制 OMS 换货单号" title="复制 OMS 换货单号" /></div><div class="exchange-number-row platform-exchange-number"><span class="number-label">平台换货单号</span><span class="number-value" :class="{ muted: !s.row.dispute_id }">{{ s.row.source_kind === 'INTERNAL' ? '无独立平台换货单' : s.row.dispute_id || '平台未返回' }}</span><el-button v-if="s.row.source_kind !== 'INTERNAL' && s.row.dispute_id" v-clipboard:copy="s.row.dispute_id" v-clipboard:success="copied" v-clipboard:error="copyFailed" type="text" icon="el-icon-document-copy" aria-label="复制平台换货单号" title="复制平台换货单号" /></div><div><el-tag size="mini" :type="s.row.source_phase === 'AFTER_SALE' ? 'warning' : ''">{{ phaseName(s.row) }}</el-tag><el-tag size="mini" effect="plain">{{ kindName(s.row) }}</el-tag><el-tag size="mini" type="info">{{ unshipped(s.row) ? '未发货替换' : '退回后换出' }}</el-tag></div><div class="muted">原平台单 {{ s.row.platform_tid || '待匹配' }}</div><div class="muted">天猫 · {{ shopName(s.row.channel_id) }}</div></template></el-table-column>
  <el-table-column label="本次商品变更" min-width="280"><template slot-scope="s"><div>{{ good(s.row.original_goods,s.row.original_sku).name || s.row.original_sku || '换回商品待匹配' }} → {{ good(s.row.target_goods,s.row.target_sku).name || s.row.target_sku || '换出商品待选择' }}</div><div class="muted sku">{{ s.row.original_sku || '—' }} → {{ s.row.target_sku || '待确认' }}</div><div class="muted">{{ good(s.row.target_goods).spec || s.row.target_description }}</div><b>批准总量 {{ s.row.requested_quantity }} 件</b><div v-if="Number(s.row.fulfillment_round) > 1" class="muted">当前第 {{ s.row.fulfillment_round }} 轮 · 本轮 {{ s.row.round_quantity }} 件</div></template></el-table-column>
  <el-table-column label="当前阶段 / 下一步" min-width="195"><template slot-scope="s"><el-tag size="small" :type="tag(s.row.state)">{{ rowTitle(s.row) }}</el-tag><div class="muted">OMS：{{ states[s.row.state] }}<span v-if="Number(s.row.fulfillment_hold)" class="muted"> · {{ ({CANCELING:'取消处理中',CANCEL_REVIEW:'取消待核对',HOLD:'已挂起',CONTINUE_REVIEW:'待继续换出审核'})[s.row.control_state] || '已暂停' }}</span></div></template></el-table-column>
  <el-table-column label="问题 / 处理时限" min-width="215"><template slot-scope="s"><el-tag v-for="code in codes(s.row.problem_codes)" :key="code" type="warning" size="mini">{{ problems[code] || code }}</el-tag><div class="warning error-summary" :title="s.row.last_error || s.row.problem_message">{{ s.row.last_error || s.row.problem_message }}</div><div v-if="!ended(s.row) && s.row.platform_deadline" :class="deadline(s.row).tone">{{ deadline(s.row).text }}</div><div v-else class="muted">{{ ended(s.row) ? '无需继续处理' : s.row.source_kind === 'INTERNAL' ? '按协商方案处理' : '平台未提供时限' }}</div></template></el-table-column>
  <el-table-column label="退回 / 验收" min-width="150"><template slot-scope="s"><span v-if="unshipped(s.row)" class="muted">无需退回</span><template v-else><div>{{ receiptSummary(s.row) }}</div><el-button type="text" size="mini" @click="openReturns(s.row.id)">查看退回与验收</el-button></template></template></el-table-column>
  <el-table-column label="平台状态" min-width="150"><template slot-scope="s"><span v-if="s.row.source_kind === 'INTERNAL'" class="muted">无独立平台流程</span><template v-else>{{ platforms[s.row.platform_status] || s.row.platform_status }}</template></template></el-table-column>
  <el-table-column label="操作" fixed="right" width="95"><template slot-scope="s"><el-button type="text" @click="open(s.row.id)">{{ s.row.control_state === 'CONTINUE_REVIEW' ? '去审核' : ended(s.row) ? '查看记录' : '去处理' }}</el-button></template></el-table-column>
 </el-table><pagination v-show="total > 0" :total="total" :page.sync="query.pageNum" :limit.sync="query.pageSize" :page-sizes="[10,20,50]" @pagination="load" />
 <el-drawer :visible.sync="visible" title="换货处理详情" size="min(1440px, 98vw)" append-to-body :wrapper-closable="false" destroy-on-close>
  <div v-if="detail" v-loading="busy" class="exchange-detail">
   <header class="identity"><div><strong>{{ detail.exchange_sn }}</strong><el-tag size="small">{{ phaseName(detail) }}</el-tag><el-tag size="small" effect="plain">{{ kindName(detail) }}</el-tag><el-tag size="small" type="info">{{ unshipped(detail) ? '未发货替换' : '退回后换出' }}</el-tag><el-tag size="small" :type="tag(detail.state)">{{ detail.control_state === 'CONTINUE_REVIEW' ? '待继续换出审核' : states[detail.state] }}</el-tag><el-tag v-if="detail.capability.simulation" size="small" type="info">本地模拟</el-tag><div v-if="detail.source_kind === 'PLATFORM'" class="exchange-number-row detail-platform-number"><span class="number-label">平台换货单号</span><span class="number-value">{{ detail.dispute_id || '平台未返回' }}</span><el-button v-if="detail.dispute_id" v-clipboard:copy="detail.dispute_id" v-clipboard:success="copied" v-clipboard:error="copyFailed" type="text" icon="el-icon-document-copy" aria-label="复制平台换货单号" title="复制平台换货单号" /></div><p class="muted">天猫 · {{ shopName(detail.channel_id) }} · 原平台单 {{ detail.platform_tid }}<span v-if="detail.source_kind === 'PLATFORM'"> · 平台：{{ platforms[detail.platform_status] || detail.platform_status }}</span></p></div><div><el-button size="small" @click="order(detail.order_id)">原业务订单</el-button><el-button size="small" @click="refreshDetail">刷新进度</el-button></div></header>
   <exchange-platform-status :exchange="detail"><el-button v-if="!editing && ['CONSIGN','reconcile','refresh'].includes(primary.action)" v-hasPermi="[primaryPermission]" size="small" :type="primary.action === 'CONSIGN' ? 'primary' : 'default'" :loading="busy" @click="runPrimary">{{ primary.label }}</el-button></exchange-platform-status>
   <p v-if="detail.platform_source" class="muted">平台来源 <router-link :to="{path:'/oms-order/platformExchanges',query:{id:detail.platform_source.id}}">{{ detail.platform_source.dispute_id }}</router-link> · 来源版本 {{ detail.platform_source.version }} · {{ detail.platform_source.source_state==='VALID'?'来源正常':'来源待核对' }}</p>
   <exchange-automatic-flow :exchange="detail" @locate="tab=$event" />
   <exchange-controls :exchange="detail" @changed="open(detail.id)" />
   <section class="next-panel"><h2>{{ current.title }}</h2><p>{{ current.description }}</p><div v-if="!ended(detail) && detail.platform_deadline" :class="deadline(detail).tone">{{ deadline(detail).text }}</div></section>
   <el-alert v-if="detail.problem_codes || detail.last_error" :closable="false" type="warning" :title="codes(detail.problem_codes).map(c => problems[c] || c).join('；') || '处理待核对'" :description="detail.last_error || detail.problem_message" />
   <el-steps :active="step" finish-status="success" simple class="flow"><el-step v-for="label in steps" :key="label" :title="label" /></el-steps>
   <el-tabs v-model="tab" class="detail-tabs">
    <el-tab-pane label="处理概览" name="overview">
     <div class="section-title"><h3>本次商品方案 · {{ detail.requested_quantity }} 件</h3><el-button v-if="detail.approved_version && !frozen && !editing" v-hasPermi="['order:exchange:review']" type="text" @click="editing = true">调整审核方案</el-button></div>
     <div class="product-comparison"><section class="product-panel"><div class="panel-label">{{ unshipped(detail) ? '本次替换的未发商品' : '本次换回商品' }}</div><exchange-source-picker v-if="!unshipped(detail)" v-model="review.source_shipment_line_id" :sources="detail.original_shipments || []" :quantity="Number(detail.requested_quantity)" :applied-quantity="detail.approved_version && !['REJECTED','CANCELED'].includes(detail.state) ? Number(detail.requested_quantity) : 0" :disabled="!editing || frozen" /><template v-else><h3>{{ good(detail.original_goods,detail.original_sku).name || detail.original_sku }}</h3><div>{{ good(detail.original_goods).spec }}</div><div class="muted">OMS SKU：{{ detail.original_sku }} · 原单明细 #{{ detail.order_line_id }}</div></template><div class="platform-description">平台原规格：{{ detail.payload.bought_sku || '未提供' }}</div></section><section class="product-panel"><div class="panel-label">本次换出商品</div><exchange-product-picker ref="targetPicker" v-model="review.target_sku" :goods="detail.target_goods || {}" :exchange-id="detail.id" :quantity="Number(detail.requested_quantity)" :original-sku="selectedSource && selectedSource.sku_sn || detail.original_sku" :disabled="!editing || frozen" :inventory-query-enabled="!ended(detail)" /><div class="platform-description">平台期望：{{ detail.target_description || '内部协商方案，无独立平台规格' }}</div></section></div>
     <el-form v-if="editing && !frozen" size="small" label-width="140px" class="review-form">
      <template v-if="!unshipped(detail)"><h3>退回与换出收货信息</h3><el-form-item label="退回虚拟仓"><el-select v-model="review.return_store" filterable><el-option v-for="w in warehouses" :key="w.wms_simulation_code" :value="w.wms_simulation_code" :label="w.wms_simulation_name + ' · ' + w.wms_simulation_code" /></el-select></el-form-item><el-form-item v-if="detail.source_kind === 'PLATFORM'" label="平台退货地址 ID"><el-input v-model.trim="review.platform_address_id" placeholder="平台已配置的退货地址 contact_id" /></el-form-item><el-form-item label="买家寄回地址"><el-input v-model="review.return_address" maxlength="500" placeholder="协商退回必填；请填写核对后的退回地址" /></el-form-item><el-form-item label="寄回联系人"><el-input v-model="review.return_contact" maxlength="200" placeholder="协商退回必填；联系人及联系电话" /></el-form-item><el-form-item label="参考收件信息"><div class="muted">{{ detail.payload.buyer_name || '姓名未返回' }} · {{ detail.payload.buyer_phone || '电话未返回' }} · {{ detail.payload.buyer_address || '地址未返回，请在平台核对' }}</div></el-form-item><el-form-item label="换出收货人"><el-input v-model="review.replacement_recipient.name" /></el-form-item><el-form-item label="换出联系电话"><el-input v-model="review.replacement_recipient.mobile" /></el-form-item><el-form-item label="换出省 / 市"><div class="two-fields"><el-input v-model="review.replacement_recipient.province" placeholder="省份" /><el-input v-model="review.replacement_recipient.city" placeholder="城市" /></div></el-form-item><el-form-item label="区 / 详细地址"><el-input v-model="review.replacement_recipient.area" placeholder="区县" /><el-input v-model="review.replacement_recipient.detailAddress" placeholder="详细地址" style="margin-top:8px" /></el-form-item><el-form-item><el-checkbox v-model="review.recipient_confirmed">已核对换出收货信息</el-checkbox></el-form-item></template>
      <el-form-item label="审核依据"><el-input v-model="review.reason" type="textarea" maxlength="500" show-word-limit placeholder="填写核对结果及协商依据" /></el-form-item><el-form-item v-if="unshipped(detail) && diffs.length"><el-button type="text" @click="tab = 'updates'">关联原订单商品更新（{{ review.difference_hashes.length }} 项已选）</el-button></el-form-item><el-form-item><el-button v-if="detail.approved_version" @click="open(detail.id)">取消调整</el-button><span class="muted">本次申请数量保持 {{ detail.requested_quantity }} 件。</span></el-form-item>
     </el-form>
     <el-descriptions v-else-if="detail.approved_version" border :column="2" size="small" class="approved-plan"><el-descriptions-item label="审核人 / 时间">{{ detail.review_by }} / {{ detail.reviewed_at }}</el-descriptions-item><el-descriptions-item label="审核依据">{{ detail.review_reason }}</el-descriptions-item><template v-if="!unshipped(detail)"><el-descriptions-item label="退回仓 / 平台地址">{{ detail.return_store }} / {{ detail.platform_address_id }}</el-descriptions-item><el-descriptions-item label="换出收货信息">{{ recipient.name }} · {{ recipient.mobile }}<div class="muted">{{ [recipient.province,recipient.city,recipient.area,recipient.detailAddress].filter(Boolean).join(' ') }}</div></el-descriptions-item></template></el-descriptions>
     <div v-if="!unshipped(detail)" class="fulfillment-panels"><section class="status-panel"><h3>退回入库与验收</h3><el-button type="text" @click="tab = 'returns'">查看退回明细与处理验收</el-button><div class="metrics"><div><span>应退</span><b>{{ detail.requested_quantity }}</b></div><div><span>仓库实收</span><b>{{ returnResult.accepted_quantity || 0 }}</b></div><div><span>已入账</span><b>{{ returnResult.posted_quantity || 0 }}</b></div><div><span>验收</span><b class="text-metric">{{ detail.return_qc === 'PASSED' ? '已确认' : '待确认' }}</b></div></div><div v-if="detail.return_sn" class="muted"><el-button type="text" @click="tab = 'returnDocuments'">管理退回单（{{ returnResult.document_count || 1 }} 张）</el-button><br>最近入库单 {{ detail.return_sn }}<router-link :to="{ path: '/oms-supplychain/wmsTickets', query: { sn: detail.return_sn, documentId: returnResult.ticket_id || undefined } }"> 查看单据与批次</router-link></div><div v-else class="muted">退回入库单尚未生成</div><router-link v-if="detail.return_sn" :to="{ path: '/oms-supplychain/wmsLogs', query: { numberType: 'DOCUMENT', number: detail.return_sn, allTime: 'true' } }">仓库交互日志</router-link></section><section class="status-panel"><h3>换出库存与发货</h3><div class="metrics"><div><span>累计应换出</span><b>{{ detail.requested_quantity }}</b></div><div><span>本轮仍预占</span><b>{{ Math.max(0, Number(stockReceipt.reserved_quantity || 0) - Number(roundShipped || 0)) }}</b></div><div><span>本轮已分仓</span><b>{{ detail.allocation_quantity || 0 }}</b></div><div><span>累计已出库</span><b>{{ exchangeOrder.shipped_quantity }}</b></div></div><div class="muted">已关联包裹 {{ packaged }} 件 · {{ packageCount }} 个包裹</div><el-button type="text" @click="tab = 'shipments'">查看换出发货与运单</el-button></section></div><section v-else class="status-panel"><h3>原单继续履约</h3><p>换品生效后，在原订单查看有效需求、审核及发货进度。</p><el-button size="small" @click="order(detail.order_id)">查看原单商品与发货</el-button></section>
    </el-tab-pane>
    <el-tab-pane v-if="!unshipped(detail)" label="退回单" name="returnDocuments" lazy><exchange-return-documents v-if="tab === 'returnDocuments'" :key="detail.id" :exchange="detail" @changed="open(detail.id)" /></el-tab-pane>
    <el-tab-pane v-if="!unshipped(detail)" label="共同退回包裹" name="sharedReturn" lazy><shared-return-panel v-if="tab==='sharedReturn'" kind="EXCHANGE" :owner="detail.id" :source="detail.id" @changed="refreshDetail" /></el-tab-pane>
    <el-tab-pane label="退回与验收" name="returns" lazy><exchange-returns v-if="tab === 'returns'" :key="detail.id" :exchange="detail" @changed="open(detail.id)" /></el-tab-pane>
    <el-tab-pane v-if="!unshipped(detail)" label="换出发货" name="shipments"><el-alert type="info" :closable="false" title="本次换出发货和出库单归本换货单，原 SO 保留销售交易和原发货记录。" /><exchange-controls :exchange="detail" outbound @changed="open(detail.id)" /><exchange-rounds :exchange="detail" @changed="open(detail.id)" /></el-tab-pane>
    <el-tab-pane label="来源与关联" name="sources"><h3>本次商品履约来源链</h3><p class="muted">本次申请 {{ detail.requested_quantity }} 件。相同 SKU 的不同次履约分别保留，各节点显示当次计划数量。</p><div class="lineage"><div v-for="(node,index) in lineageChain" :key="node.line_id" :class="['lineage-node',{ current: Number(node.line_id) === Number(detail.fulfillment_line_id || detail.order_line_id) }]"><span class="node-index">{{ index + 1 }}</span><div><strong>{{ node.sku_sn }} · {{ node.quantity }} 件</strong><div>{{ node.goods_name }}</div><el-button v-if="node.exchange_id" type="text" @click="open(node.exchange_id)">{{ node.exchange_sn }}</el-button><div v-else class="muted">初购商品</div><div class="muted">履约明细 #{{ node.line_id }}<span v-if="node.cancelled_quantity"> · 已终止 {{ node.cancelled_quantity }} 件</span></div><router-link v-for="source in lineageShipments(node)" :key="source.source_shipment_line_id" :to="{ path: '/oms-order/shipments', query: { number: source.shipment_sn } }"><div class="muted">{{ source.shipment_sn }} · 发货明细 #{{ source.source_shipment_line_id }}</div></router-link></div></div></div><el-alert v-if="!lineageChain.length" :closable="false" type="info" title="实际来源尚未确定，请先核对来源。" /><el-collapse class="source-info"><el-collapse-item title="平台身份与来源编号"><el-descriptions :column="2" border size="small"><el-descriptions-item label="平台换货单号">{{ detail.dispute_id || '无独立平台申请' }}</el-descriptions-item><el-descriptions-item label="原平台子单">{{ detail.platform_oid }}</el-descriptions-item><el-descriptions-item label="本次退回来源">{{ sourceBasis.original_shipment_sn || '未发货来源' }} · 明细 #{{ detail.source_shipment_line_id || detail.order_line_id }}</el-descriptions-item><el-descriptions-item label="平台最新修改">{{ detail.source_modified }}</el-descriptions-item><el-descriptions-item label="平台时限">{{ detail.platform_deadline || '未提供' }}</el-descriptions-item><el-descriptions-item label="平台操作">{{ operations[detail.platform_operation] }}</el-descriptions-item></el-descriptions></el-collapse-item></el-collapse></el-tab-pane>
    <el-tab-pane v-if="unshipped(detail) || diffs.length || detail.update_links.length" label="订单更新关联" name="updates"><el-alert :closable="false" type="info" title="审核时保存所选商品差异的关联，履约生效后解除对应阻断；其他金额、退款或挂起问题保留。" /><el-table :data="diffs" @selection-change="selectDiffs"><el-table-column type="selection" width="45" :selectable="canSelect" /><el-table-column label="类型" prop="category" width="100" /><el-table-column label="平台子单" prop="platform_oid" min-width="180" /><el-table-column label="字段" prop="field" min-width="130" /><el-table-column label="采用值" prop="before" min-width="160" /><el-table-column label="平台最新值" prop="after" min-width="160" /></el-table><el-table :data="detail.update_links" empty-text="暂无关联差异"><el-table-column label="关联字段" prop="field_path" /><el-table-column label="生效状态"><template slot-scope="s">{{ s.row.state === 'APPLIED' ? '已生效' : s.row.state === 'LINKED' ? '已关联，待履约生效' : s.row.state }}</template></el-table-column><el-table-column label="生效时间" prop="applied_at" /></el-table></el-tab-pane>
    <el-tab-pane label="处理记录" name="events"><el-timeline class="events"><el-timeline-item v-for="event in detail.events" :key="event.id" :timestamp="event.create_time"><strong>{{ eventNames[event.action] || '业务处理' }}</strong> · {{ event.actor }}<p>{{ event.message }}</p></el-timeline-item></el-timeline><el-empty v-if="!detail.events.length" description="暂无处理记录" /></el-tab-pane>
   </el-tabs>
  </div>
  <footer v-if="detail" class="detail-footer"><div class="footer-hint"><strong>{{ editing && !frozen ? '请核对审核方案' : current.title }}</strong><div class="muted">{{ primaryBlock || current.description }}</div></div><div class="footer-actions"><el-dropdown v-if="detail.source_kind === 'PLATFORM'" v-hasPermi="['order:exchange:sync','order:exchange:execute']" trigger="click" @command="moreAction"><el-button size="small">更多操作<i class="el-icon-arrow-down el-icon--right" /></el-button><el-dropdown-menu slot="dropdown"><el-dropdown-item v-hasPermi="['order:exchange:sync']" command="refresh">刷新平台申请</el-dropdown-item><el-dropdown-item v-hasPermi="['order:exchange:execute']" v-if="!detail.linked_exchange_id && detail.platform_status === '1' && detail.platform_operation === 'NONE' && !ended(detail)" command="refuse">拒绝平台申请</el-dropdown-item></el-dropdown-menu></el-dropdown><el-button v-if="detail.linked_exchange_id" size="small" @click="open(detail.linked_exchange_id)">查看关联协商单</el-button><el-button v-if="detail.source_kind === 'INTERNAL' && !unshipped(detail) && detail.approved_version" v-hasPermi="['order:exchange:review']" size="small" @click="openLink">核对关联平台申请</el-button><el-button size="small" @click="visible = false">关闭</el-button><el-button v-if="primary.action" :key="primary.action" v-hasPermi="[primaryPermission]" size="small" type="primary" :loading="busy" :disabled="!!primaryBlock" @click="runPrimary">{{ primary.label }}</el-button></div></footer>
 </el-drawer>
 <el-dialog :title="operationTitle" :visible.sync="operationVisible" width="580px" append-to-body :close-on-click-modal="false"><el-alert :closable="false" type="info" :title="operationDescription" /><el-form label-width="90px" style="margin-top:18px"><el-form-item label="处理依据"><el-input v-model="operationReason" type="textarea" maxlength="500" show-word-limit /></el-form-item></el-form><span slot="footer"><el-button @click="operationVisible = false">取消</el-button><el-button type="primary" :loading="busy" :disabled="!operationReason.trim()" @click="confirmOperation">确认{{ operationTitle }}</el-button></span></el-dialog>
    <el-dialog title="创建协商换货" :visible.sync="createVisible" width="min(980px, 96vw)" :close-on-click-modal="false"><el-alert type="info" :closable="false" title="售中 / 售后表示交易阶段；履约方式按所选商品是否实际发货区分。平台申请请优先同步，避免重复创建。" /><el-form label-width="130px" style="margin-top:20px"><el-form-item label="履约方式"><el-radio-group v-model="createForm.fulfillment_mode" @change="changeCreateMode"><el-radio label="UNSHIPPED">未发货替换</el-radio><el-radio label="RETURN">退回后换出</el-radio></el-radio-group></el-form-item><el-form-item label="换货阶段"><el-select v-model="createForm.source_phase"><el-option label="售中换货" value="DURING_SALE" /><el-option label="售后换货" value="AFTER_SALE" :disabled="createForm.fulfillment_mode === 'UNSHIPPED'" /></el-select><div class="muted">客服根据已核对交易阶段选择；已发货不等于售后。</div></el-form-item><el-form-item label="原 OMS / 平台单号"><el-input v-model.trim="originalNumber" placeholder="输入完整 OMS 或平台单号" @input="clearCreateOrder" @keyup.enter.native="findOriginal"><el-button slot="append" :loading="findingOrder" @click="findOriginal">查找</el-button></el-input><div v-if="createOrder" class="hint">已选原单：{{ createOrder.order_sn }}</div></el-form-item><el-form-item v-if="createForm.fulfillment_mode === 'UNSHIPPED'" label="未发货商品"><el-select v-model="createForm.order_line_id" :disabled="!createOrder" placeholder="先查找原订单，再选择未发货商品" @change="selectCreateLine"><el-option v-for="line in createLines" :key="line.id" :value="line.id" :label="line.sku_sn + ' · 未发 ' + (Number(line.quantity) - Number(line.cancelled_quantity || 0) - Number(line.shipped_quantity || 0)) + ' 件 · ' + (line.exchange_sn || '原购商品')" /></el-select></el-form-item><el-form-item v-else label="实际退回来源"><exchange-source-picker v-if="createOrder" v-model="createForm.source_shipment_line_id" :sources="createReturnSources" :quantity="Number(createForm.quantity)" @input="selectCreateSource" /><span v-else class="muted">先查找原订单，再选择已出库的实际发货明细。</span></el-form-item><el-form-item label="换货数量"><el-input-number :key="String(createForm.order_line_id) + '/' + String(createForm.source_shipment_line_id) + '/' + createQuantityMax" v-model="createForm.quantity" :min="1" :max="createQuantityMax" :disabled="!createForm.platform_oid" /></el-form-item><el-form-item label="换出商品"><exchange-product-picker v-model="createForm.target_sku" :order-id="createForm.order_id" :quantity="Number(createForm.quantity)" :original-sku="createOriginalSku" /></el-form-item><template v-if="createForm.fulfillment_mode === 'RETURN'"><el-form-item label="退回虚拟仓"><el-select v-model="createForm.return_store" filterable><el-option v-for="w in warehouses" :key="w.wms_simulation_code" :value="w.wms_simulation_code" :label="w.wms_simulation_name + ' · ' + w.wms_simulation_code" /></el-select></el-form-item><el-form-item label="买家寄回地址"><el-input v-model="createForm.return_address" maxlength="500" /></el-form-item><el-form-item label="寄回联系人"><el-input v-model="createForm.return_contact" maxlength="200" /></el-form-item><el-form-item label="换出收件人"><el-input v-model="createForm.replacement_recipient.name" /></el-form-item><el-form-item label="换出联系电话"><el-input v-model="createForm.replacement_recipient.mobile" /></el-form-item><el-form-item label="换出省 / 市"><div class="two-fields"><el-input v-model="createForm.replacement_recipient.province" placeholder="省" /><el-input v-model="createForm.replacement_recipient.city" placeholder="市" /></div></el-form-item><el-form-item label="换出区 / 地址"><el-input v-model="createForm.replacement_recipient.area" placeholder="区县" /><el-input v-model="createForm.replacement_recipient.detailAddress" placeholder="详细地址" style="margin-top:8px" /></el-form-item></template><el-form-item label="允许规则自动处理"><el-checkbox v-model="createForm.automation_authorized">已获商家明确授权，按店铺规则自动审核及推进</el-checkbox><el-input v-if="createForm.automation_authorized" v-model.trim="createForm.authorization_reference" maxlength="200" placeholder="业务授权 / 协商工单编号" /></el-form-item><el-form-item label="协商依据 / 凭证"><el-input v-model="createForm.reason" type="textarea" maxlength="500" show-word-limit /></el-form-item></el-form><span slot="footer"><el-button @click="createVisible=false">取消</el-button><el-button type="primary" :loading="busy" @click="submitCreate">{{ createForm.fulfillment_mode === 'RETURN' ? '创建协商换货，待审核' : '创建并暂停原单新增履约' }}</el-button></span></el-dialog>
    <el-dialog title="核对关联平台换货申请" :visible.sync="linkVisible" width="min(760px,96vw)" :close-on-click-modal="false"><el-alert title="仅关联尚未审核或执行的平台申请；沿用协商单实物与库存记录，不重复履约。平台同意、收货和物流操作需人工在平台核对。" type="warning" :closable="false" /><el-input v-model.trim="linkNumber" placeholder="输入平台换货单号或 OMS 换货单号" style="margin:16px 0"><el-button slot="append" @click="findLink">查找</el-button></el-input><el-select v-model="linkId" placeholder="选择已核对的同一申请" style="width:100%"><el-option v-for="e in linkRows" :key="e.id" :value="e.id" :label="e.exchange_sn + ' · 平台 ' + e.dispute_id + ' · ' + e.requested_quantity + ' 件'" /></el-select><el-input v-model="linkReason" type="textarea" maxlength="500" placeholder="请核对买家、目标商品、实际来源、数量和已执行事实，填写关联依据" style="margin-top:16px" /><el-checkbox v-model="linkConfirmed" style="margin-top:14px">已核对买家、实际来源、目标商品及数量一致</el-checkbox><span slot="footer"><el-button @click="linkVisible=false">取消</el-button><el-button type="primary" :loading="busy" @click="submitLink">确认核对关联</el-button></span></el-dialog>
    <el-dialog title="拒绝平台换货申请" :visible.sync="refuseVisible" width="580px"><el-form label-width="100px"><el-form-item label="平台原因"><el-select v-model="refuseForm.seller_refuse_reason_id"><el-option v-for="r in reasons" :key="r.reason_id" :value="String(r.reason_id)" :label="r.reason_text" /></el-select></el-form-item><el-form-item label="处理依据"><el-input v-model="refuseForm.reason" type="textarea" maxlength="500" /></el-form-item></el-form><span slot="footer"><el-button @click="refuseVisible=false">取消</el-button><el-button type="danger" :loading="busy" @click="execute('REFUSE', refuseForm)">提交平台拒绝</el-button></span></el-dialog>
</div>
</template>
<script>
import ExchangePlatformStatus from './ExchangePlatformStatus'
import { exchangeWorkbench, exchangeDetail, exchangeAction, exchangeCreate, exchangeReasons, exchangeCatalog, exchangeCreateSources } from '@/api/order/exchange'
import { orderList, orderDetail } from '@/api/order'
import ExchangeReturns from './ExchangeReturns'
import ExchangeControls from './ExchangeControls'
import ExchangeAutomaticFlow from './ExchangeAutomaticFlow'
import SharedReturnPanel from './SharedReturnPanel'
import ExchangeReturnDocuments from './ExchangeReturnDocuments'
import ExchangeRounds from './ExchangeRounds'
import ExchangeProductPicker from './ExchangeProductPicker'
import ExchangeSourcePicker from './ExchangeSourcePicker'
import { states, stages, platforms, problems, operations } from './exchangeLabels'
import { good, progress, ended, buckets, eventNames, unshipped, phaseName } from './exchangePresentation'
export default {
 name: 'OrderExchanges', components: { SharedReturnPanel, ExchangeAutomaticFlow, ExchangePlatformStatus, ExchangeControls, ExchangeReturnDocuments, ExchangeReturns, ExchangeRounds, ExchangeProductPicker, ExchangeSourcePicker },
 data() { return { states, stages, platforms, problems, operations, buckets, eventNames, more: false, counts: {}, query: { phase: '', number: '', channelId: undefined, state: '', kind: '', problem: '', bucket: 'ALL', pageNum: 1, pageSize: 20 }, rows: [], shops: [], warehouses: [], total: 0, loading: false, busy: false, listError: false, visible: false, detail: null, review: {}, editing: false, tab: 'overview', listSequence: 0, detailSequence: 0, operationVisible: false, operation: '', operationReason: '', syncVisible: false, syncMode: 'time', syncForm: {}, range: [], tasksVisible: false, tasks: [], createVisible: false, createForm: {}, createReturnSources: [], linkVisible: false, linkNumber: '', linkId: undefined, linkRows: [], linkReason: '', linkConfirmed:false, originalNumber: '', createOrder: null, findingOrder: false, refuseVisible: false, reasons: [], refuseForm: {} } },
 computed: {
  sourceBasis() { return this.detail && this.detail.approved_snapshot && this.detail.approved_snapshot.return_basis || {} }, recipient() { return this.detail.round_recipient ? this.parse(this.detail.round_recipient) : this.detail.approved_snapshot && this.detail.approved_snapshot.replacement_recipient || {} }, returnResult() { return this.detail.return_result || {} }, stockReceipt() { return this.parse(this.detail.stock_receipt) },
  frozen() { return !!(this.detail && (this.detail.stock_request || this.detail.fulfillment_line_id || Number(this.detail.fulfillment_round) > 1 || ended(this.detail) || this.detail.linked_exchange_id)) },
  current() { return this.detail ? progress(this.detail) : {} }, primary() { return this.editing && !this.frozen ? { action: 'review', label: '保存审核方案' } : this.current }, primaryPermission() { return this.primary.action === 'review' ? 'order:exchange:review' : this.primary.action === 'refresh' ? 'order:exchange:sync' : ['order','shipments','returns'].includes(this.primary.action) ? 'order:order:query' : 'order:exchange:execute' },
  primaryBlock() { if (this.primary.action !== 'review') return ''; if (!this.review.target_sku) return '请先选择换出商品'; if (!unshipped(this.detail) && !this.review.source_shipment_line_id) return '请先选择实际退回来源'; if (this.selectedSource && Number(this.selectedSource.claimable_quantity) < Number(this.detail.requested_quantity)) return '所选来源可申请数量不足，请核对平台申请'; if (!unshipped(this.detail) && (!this.review.return_store || this.detail.source_kind === 'PLATFORM' && !this.review.platform_address_id || !this.review.recipient_confirmed || this.detail.source_kind === 'INTERNAL' && (!this.review.return_address || !this.review.return_contact))) return '请完善退回仓库、平台地址并核对换出收件信息'; if (!(this.review.reason || '').trim()) return '请填写审核依据'; return '' },
  selectedSource() { return ((this.detail || {}).original_shipments || []).find(s => Number(s.source_shipment_line_id) === Number(this.review.source_shipment_line_id)) },
  steps() { return unshipped(this.detail) ? ['审核方案','撤回原发货','换品生效','原单继续发货'] : this.detail.source_kind === 'INTERNAL' ? ['审核方案','退回与验收','换出发货','完成'] : ['审核方案','同意申请','退回验收','换出发货','回传物流'] }, step() { return ended(this.detail) && this.detail.state === 'COMPLETED' ? this.steps.length : Math.min(this.current.step || 0,this.steps.length - 1) },
  packaged() { return (this.detail.shipments || []).reduce((n,s) => n + Number(s.packaged_quantity || 0),0) }, packageCount() { return (this.detail.shipments || []).reduce((n,s) => n + Number(s.package_count || 0),0) },
  roundShipped() { return (this.detail.shipments || []).filter(s => Number(s.fulfillment_round) === Number(this.detail.fulfillment_round)).reduce((n,s) => n + Number(s.shipped_quantity || 0),0) },
  exchangeOrder() { const e = this.detail || {}; const ships = e.shipments || []; return { id: e.order_id, fulfillment_owner: 'EXCHANGE', status: 'WAIT_ALLOCATION', shipments: ships, allocation_quantity: e.allocation_quantity, pending_allocation_quantity: Math.max(0,Number(e.requested_quantity || 0) - Number(e.allocation_quantity || 0)), shipped_quantity: ships.reduce((n,s) => n + Number(s.shipped_quantity || 0),0), shipment_count: ships.length, warehouse_accepted_quantity: ships.filter(s => s.wms_dispatch_state === 'ACCEPTED').reduce((n,s) => n + Number(s.quantity || 0),0) } },
  lineageChain() { const e = this.detail || {}; const nodes = new Map((e.lineage || []).map(n => [Number(n.line_id),n])); let id = Number(e.fulfillment_line_id || (e.source_kind === 'PLATFORM' ? (this.selectedSource && this.selectedSource.order_line_id || (e.source_shipment_line_id ? e.order_line_id : 0)) : e.order_line_id)); const seen = new Set(); const chain = []; while (id && nodes.has(id) && !seen.has(id) && chain.length < 100) { seen.add(id); const node = nodes.get(id); chain.unshift(node); id = Number(node.source_line_id) } return chain },
  createLines() { return ((this.createOrder || {}).lines || []).filter(l => Number(l.quantity) - Number(l.cancelled_quantity || 0) - Number(l.shipped_quantity || 0) > 0) }, createQuantityMax() { if(this.createForm.fulfillment_mode === 'RETURN'){const source=this.createReturnSources.find(s=>Number(s.source_shipment_line_id)===Number(this.createForm.source_shipment_line_id));return source ? Math.max(1, Number(source.claimable_quantity)) : 1} const line = this.createLines.find(l => l.id === this.createForm.order_line_id); return line ? Number(line.quantity) - Number(line.cancelled_quantity || 0) - Number(line.shipped_quantity || 0) : 1 }, createOriginalSku() { return this.createForm.fulfillment_mode === 'RETURN' ? (this.createReturnSources.find(s=>Number(s.source_shipment_line_id)===Number(this.createForm.source_shipment_line_id))||{}).sku_sn : (this.createLines.find(l => l.id === this.createForm.order_line_id) || {}).sku_sn }, diffs() { return this.detail && this.detail.order_update ? this.detail.order_update.differences : [] },
  operationTitle() { return ({ AGREE: '同意平台申请', RECEIVED: '确认平台退回收货', CONSIGN: '回传换出物流', qc: '确认退回验收', advance: this.current.label, allocate: '分仓换出商品' })[this.operation] || '执行业务处理' },
  operationDescription() { return ({ AGREE: '重新检查并预占换出库存，满足后向平台提交同意；不足时保留申请数量。', RECEIVED: '实际退回已入账且已验收，本次向平台确认收货，不重复增加库存。', CONSIGN: '使用本次已出库并关联包裹的物流，向平台提交换货发货。', qc: '核对实际退回商品、数量和批次后确认验收，不重复增加库存。', allocate: '按本次方案和店铺允许仓分配换出商品，确认后形成仓库占用。', advance: this.current.description })[this.operation] || '' }
 },
 async created() { const c = (await exchangeCatalog()).data; this.shops = c.channels || []; this.warehouses = c.warehouses || []; await this.load(); if (this.$route.query.exchangeId) this.open(this.$route.query.exchangeId) },
 watch: { '$route.query.exchangeId'(id) { if (id) this.open(id) } },
 methods: {
  copied() { this.$message.success('单号已复制') }, copyFailed() { this.$message.error('复制失败，请选中单号手动复制') },
  good, progress, ended, unshipped, phaseName, kindName(e) { return e.source_kind === 'INTERNAL' ? '客服协商' : '平台申请' }, parse(v) { if (!v) return {}; if (typeof v === 'object') return v; try { return JSON.parse(v) } catch (_) { return {} } },
  codes(v) { return (v || '').split(',').filter(Boolean) }, shopName(id) { const s = this.shops.find(c => String(c.channel_id) === String(id)); return s ? s.channel_name : '渠道 ' + id }, tag(s) { return s === 'COMPLETED' ? 'success' : ['BLOCKED','WAIT_STOCK'].includes(s) ? 'warning' : ['REJECTED','CANCELED'].includes(s) ? 'info' : '' },
  rowTitle(e) { if (e.control_state === 'CONTINUE_REVIEW' || ended(e) || !e.approved_version || ['BLOCKED','WAIT_STOCK'].includes(e.state)) return progress(e).title; return ({ RETURN: '待退回 / 验收', SHIP: unshipped(e) ? '原单继续发货' : '待换出发货', PLATFORM: '待平台处理' })[e.work_bucket] || progress(e).title },
  deadline(e) { const hours = (new Date(String(e.platform_deadline).replace(/-/g,'/')).getTime() - Date.now()) / 3600000; return { tone: hours < 0 ? 'danger' : hours < 24 ? 'warning' : 'muted', text: hours < 0 ? '处理时限已过 · 请核对平台' : hours < 24 ? '剩余约 ' + Math.max(1,Math.ceil(hours)) + ' 小时' : '截止 ' + e.platform_deadline } },
  async load() { const seq = ++this.listSequence; this.loading = true; this.listError = false; try { const d = (await exchangeWorkbench(this.query)).data; if (seq !== this.listSequence) return; this.rows = d.rows; this.total = d.total; this.counts = d.counts } catch (_) { if (seq === this.listSequence) { this.rows = []; this.total = 0; this.counts = {}; this.listError = true } } finally { if (seq === this.listSequence) this.loading = false } }, search() { this.query.pageNum = 1; this.load() }, changeBucket(tab) { this.query.bucket = tab.name; this.search() }, reset() { Object.assign(this.query,{ number: '',channelId: undefined,state: '',kind: '',problem: '',phase: '',bucket: 'ALL',pageNum: 1 }); this.load() },
  async open(id) { const seq = ++this.detailSequence; this.busy = true; try { const d = (await exchangeDetail(id)).data; if (seq !== this.detailSequence) return; const changed = !this.detail || Number(this.detail.id) !== Number(id); this.detail = d; this.review = { source_shipment_line_id: d.source_shipment_line_id || ((d.original_shipments || []).length === 1 ? d.original_shipments[0].source_shipment_line_id : undefined),target_sku: d.target_sku,return_store: d.return_store,return_address: (d.approved_snapshot || d.payload).return_address || '',return_contact: (d.approved_snapshot || d.payload).return_contact || '',platform_address_id: d.platform_address_id,reason: d.review_reason || '',recipient_confirmed: false,replacement_recipient: { ...(d.approved_snapshot && d.approved_snapshot.replacement_recipient || d.payload.replacement_recipient || d.replacement_recipient || {}) },difference_hashes: [] }; this.editing = !d.approved_version && !this.frozen && d.platform_operation === 'NONE' && d.state !== 'BLOCKED' && Number(d.speed_exchange) !== 1; if (changed) this.tab = 'overview'; this.visible = true } finally { if (seq === this.detailSequence) this.busy = false } },
  async refreshDetail() { if (this.editing) { try { await this.$confirm('刷新会重新加载已保存方案，尚未保存的编辑将清除。','刷新进度',{ type: 'warning' }) } catch (_) { return } } await this.open(this.detail.id) },
  async action(name,body = {}) { const id = this.detail.id; this.busy = true; try { await exchangeAction(id,name,{ ...body,control_version: this.detail.control_version }); this.operationVisible = false; this.$message.success('操作已提交，请查看最新进度'); await this.open(id); await this.load() } finally { this.busy = false } },
  order(id) { this.$router.push({ path: '/oms-order/business',query: { view: 'business',orderId: id } }) },
  canSelect(d) { return this.editing && !this.frozen && d.category === 'GOODS' && d.platform_oid === this.detail.platform_oid }, selectDiffs(rows) { this.review.difference_hashes = rows.map(d => d.difference_hash) }, lineageShipments(node) { return (this.detail.original_shipments || []).filter(s => Number(s.order_line_id) === Number(node.line_id)) },
  async runPrimary() { const action = this.primary.action; if (action === 'review') { await this.action('review',this.review); return } if (action === 'order') return this.order(this.detail.order_id); if (['returns','qc'].includes(action)) { this.tab='returns'; return } if (action === 'shipments') { this.tab = 'shipments'; return } if (['refresh','reconcile'].includes(action)) return this.action(action); this.operation = action; this.operationReason = ''; this.operationVisible = true },
  async confirmOperation() { const body = { reason: this.operationReason }; if (['AGREE','RECEIVED','CONSIGN'].includes(this.operation)) await this.action('execute',{ ...body,operation: this.operation }); else await this.action(this.operation,body) },
  async moreAction(name) { if (name === 'refuse') return this.refuse(); if (this.editing) { try { await this.$confirm('刷新平台申请会重新加载方案，尚未保存的编辑将清除。','刷新平台申请',{ type: 'warning' }) } catch (_) { return } } await this.action(name) }, async execute(operation,extra = {}) { await this.$confirm('确认按已核对的原因向平台提交拒绝？','拒绝平台申请',{ type: 'warning' }); await this.action('execute',{ operation,reason: this.review.reason,...extra }); this.refuseVisible = false },
    async refuse() { this.reasons = (await exchangeReasons(this.detail.id)).data.reasons; this.refuseForm = { seller_refuse_reason_id: '', reason: '' }; this.refuseVisible = true },
    openSync() { this.$router.push({path:'/oms-order/syncTasks',query:{kind:'EXCHANGE',action:'backfill',...(this.query.channelId?{channelId:this.query.channelId}:{})}}) },
    showTasks() { this.$router.push({path:'/oms-order/syncTasks',query:{kind:'EXCHANGE',tab:'tasks'}}) },
    clearCreateOrder(){this.createOrder=null;this.createReturnSources=[];this.createForm.order_id='';this.createForm.order_line_id=undefined;this.createForm.source_shipment_line_id=undefined;this.createForm.platform_oid='';this.createForm.target_sku=''},
    selectCreateLine(){const line=this.createLines.find(l=>l.id===this.createForm.order_line_id);this.createForm.platform_oid=line?line.platform_oid:''},
    openCreate() { this.originalNumber = ''; this.createOrder = null; this.createReturnSources=[]; this.createForm = { fulfillment_mode:'UNSHIPPED',source_phase:'DURING_SALE',order_id:'',order_line_id:undefined,source_shipment_line_id:undefined,platform_oid:'',quantity:1,target_sku:'',return_store:'',return_address:'',return_contact:'',replacement_recipient:{},automation_authorized:false,authorization_reference:'',reason:'',request_key:this.key() };this.createVisible=true },
    changeCreateMode(){this.createForm.source_phase=this.createForm.fulfillment_mode==='UNSHIPPED'?'DURING_SALE':'';this.clearCreateOrder()},
    selectCreateSource(id){this.createForm.source_shipment_line_id=id;const source=this.createReturnSources.find(s=>Number(s.source_shipment_line_id)===Number(id));this.createForm.order_line_id=source&&source.order_line_id;this.createForm.platform_oid=source&&source.platform_oid||''},
    async findOriginal(){
      if(!this.originalNumber||this.findingOrder)return;const number=this.originalNumber,mode=this.createForm.fulfillment_mode;const current=()=>this.createVisible&&this.originalNumber===number&&this.createForm.fulfillment_mode===mode;
      this.findingOrder=true;this.clearCreateOrder();try{const r=await orderList('business',{tid:number,pageNum:1,pageSize:20});if(!current())return;const rows=r.rows.filter(o=>o.business_type==='SALE'&&(mode==='RETURN'?!['VOIDED','VOIDING'].includes(o.status):o.status==='WAIT_ALLOCATION'));if(rows.length!==1)return this.$message.warning('未找到唯一可处理原订单，请核对完整单号与履约方式');const selected=(await orderDetail('business',rows[0].id)).data;if(!current())return;
      if(mode==='RETURN'){const context=(await exchangeCreateSources(selected.id)).data;if(!current())return;this.createOrder=selected;this.createForm.order_id=selected.id;this.createReturnSources=context.sources;this.createForm.replacement_recipient={...context.recipient};if(!this.createReturnSources.length)this.$message.warning('该订单没有已出库的实际发货来源')}else{this.createOrder=selected;this.createForm.order_id=selected.id;if(this.createLines.length===1){this.createForm.order_line_id=this.createLines[0].id;this.selectCreateLine()}if(!this.createLines.length)this.$message.warning('该订单没有未发货数量')}}finally{this.findingOrder=false}
    },
    async submitCreate(){if(!this.createForm.source_phase)return this.$message.warning('请选择已核对的售中 / 售后换货阶段');if(!this.createOrder||!this.createForm.platform_oid)return this.$message.warning('请查找原订单并选择实际商品来源');if(this.createForm.fulfillment_mode==='RETURN'&&(!this.createForm.return_store||!this.createForm.return_address||!this.createForm.return_contact))return this.$message.warning('请填写退回仓、买家寄回地址和联系人');if(!(this.createForm.reason||'').trim())return this.$message.warning('请填写协商依据');this.busy=true;try{const r=await exchangeCreate(this.createForm);this.createVisible=false;await this.open(r.data.id);await this.load()}finally{this.busy=false}},
    receiptSummary(e){if(e.linked_exchange_id)return '沿用关联协商单';if(e.return_qc==='ISSUE')return '差异待处理';if(e.return_qc==='PASSED')return '已验收';return ({COMPLETED:'待验收',PARTIAL:'部分收货',POSTING:'记账中',POSTING_FINAL:'记账中'})[e.return_receipt_state]||(e.return_sn?'待收货':'待准备退回')},
    async openReturns(id){await this.open(id);if(this.detail&&Number(this.detail.id)===Number(id))this.tab='returns'},
    openLink(){this.linkNumber='';this.linkRows=[];this.linkId=undefined;this.linkReason='';this.linkConfirmed=false;this.linkVisible=true},
    async findLink(){if(!this.linkNumber)return;const r=(await exchangeWorkbench({number:this.linkNumber,pageNum:1,pageSize:20})).data;this.linkRows=r.rows.filter(e=>e.source_kind==='PLATFORM'&&Number(e.order_id)===Number(this.detail.order_id)&&!e.approved_version&&!e.linked_exchange_id);if(!this.linkRows.length)this.$message.warning('未找到同一原单下尚未执行的平台申请')},
    async submitLink(){if(!this.linkId||!this.linkReason.trim()||!this.linkConfirmed)return this.$message.warning('请选择已核对的平台申请并填写依据');await this.action('link-platform',{platform_exchange_id:this.linkId,reason:this.linkReason,confirmed:this.linkConfirmed});this.linkVisible=false},
    key() { return 'EX' + Date.now().toString(36) + Math.random().toString(36).slice(2, 16) }, format(d) { const pad = x => String(x).padStart(2, '0'); return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}` }
 }
}
</script>
